function fixStoryHero(){const story=document.querySelector('#hero-our-story');if(!story)return;const link=story.querySelector('.supplied-banner-link');if(!link)return;let pic=link.querySelector('picture');if(!pic){const img=link.querySelector('img');if(!img)return;pic=document.createElement('picture');pic.innerHTML='<source media="(max-width: 700px)" srcset="/assets/campaigns/hero-story-mobile.webp">';img.parentNode.insertBefore(pic,img);pic.appendChild(img)}else if(!pic.querySelector('source[media*="700px"]'))pic.insertAdjacentHTML('afterbegin','<source media="(max-width: 700px)" srcset="/assets/campaigns/hero-story-mobile.webp">');const img=pic.querySelector('img');if(img)img.src='/assets/campaigns/hero-story-unified.webp'}
